DROP TABLE IF EXISTS `competition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `competition` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `opponent_name` varchar(255) NOT NULL,
  `opponent_points` varchar(255) NOT NULL,
  `personal_points` varchar(255) NOT NULL,
  `event_date` datetime NOT NULL COMMENT '(DC2Type:datetime_immutable)',
  `title_fr` tinytext NOT NULL,
  `win` tinyint(1) NOT NULL,
  `personal_overs` double NOT NULL,
  `opponent_overs` double NOT NULL,
  `content_fr` longtext DEFAULT NULL,
  `created_at` datetime NOT NULL COMMENT '(DC2Type:datetime_immutable)',
  `updated_at` datetime NOT NULL COMMENT '(DC2Type:datetime_immutable)',
  `image` varchar(255) NOT NULL,
  `title_en` tinytext NOT NULL,
  `content_en` longtext DEFAULT NULL,
  `translation_version_hash` longtext DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

