INSERT INTO `news` VALUES (6,'D√©couverte du cricket aux centres a√©r√©s et camping pendant de vacances d\'√©t√©','decouverte-du-cricket-aux-centres-aeres-et-camping-pendant-de-vacancies-dete','<ul><li>Permettre aux enfants et aux jeunes de vivre un vrai temps de <strong>loisirs collectif</strong>.</li><li>Amener le public √† d√©couvrir des pratiques nouvelles, vari√©es et une nouvelle discipline aux Jeux Olympiques de Los Angeles 2028.</li><li>Favoriser l‚Äôacquisition des savoirs techniques, la tol√©rance, l‚Äôexpression de la solidarit√© et la reconnaissance de la diversit√© ch√®res √† la discipline Cricket.</li><li>Favoriser l‚Äô√©change avec les autres centres de loisirs, (enfants - adultes).</li><li>Permettre aux animateurs de se former sur une discipline traditionnelle qui se pratique selon des r√®glements adapt√©s, s√©curitaires (bien diff√©rents de la pratique √† haut niveau) et accessibles √† tous publics&nbsp;</li></ul><div><br>TARIFS ET EQUIPEMENTS<br>Nous r√©fl√©chissons avec vous √† la formule la plus adapt√©e √† vos besoins.</div>','2024-06-13-afb9e1fe-906e-4256-b8c2-935c756ad972.png','2024-06-13 12:33:50','2026-03-29 18:44:26','Discovered cricket at summer camps and camping during summer holidays','<ul><li>Allow children and young people to experience a real time of <strong>collective leisure</strong>.</li>\n<li>Encourage the public to discover new, varied practices and a new discipline at the Los Angeles 2028 Olympic Games.</li>\n<li>Promote the acquisition of technical knowledge, tolerance, the expression of solidarity, and the recognition of diversity valued in the discipline of Cricket.</li>\n<li>Encourage exchange with other leisure centers (children - adults).</li>\n<li>Enable facilitators to train in a traditional discipline practiced according to adapted, safe rules (very different from high-level practice) and accessible to all audiences.</li>\n</ul>\n<div><br>\nPRICING AND EQUIPMENT<br>\nWe work with you to find the formula best suited to y